+      }
+      ul {
+        padding-inline-start: 2em;
+      }
+      #folderList {
+        white-space: nowrap;
+        overflow: hidden auto;
+        margin: 0;
+      }
+      #folderList + div {
+        flex: 1;
+        display: flex;
+        flex-direction: column;
+      }
+      #messageList {
+        flex: 1;
+      }
+    </style>
+  </head>
+  <body>
+    <ul id="folderList"></ul>
+    <div>
+      <div>
+        View type:
+        <label
+          ><input
+            id="all_messages"
+            type="radio"
+            name="viewType"
+            checked="checked"
+          />
+          All</label
+        >
+        <label
+          ><input id="unread_messages" type="radio" name="viewType" /> Unread
+          only</label
+        >
+      </div>
+      <auto-tree-view id="messageList"></auto-tree-view>
+    </div>
+  </body>
+</html>
